    total = 4 + (is_major_sync?28:0) + 2 + substr_bytes;
    if(total & 1){ fprintf(stderr,"total odd!\n"); exit(1);} 

    /* length field: big endian, low 12 bits = total/2 */
    p[0] = 0;                      /* top nibble free */
    p[1] = (total/2)&0xff;
    if((total/2)>>8){ p[0] = ((total/2)>>8)&0x0f; }
