#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

uint8_t  ff_mlp_checksum8 (const uint8_t *buf, unsigned int buf_size);
uint16_t ff_mlp_checksum16(const uint8_t *buf, unsigned int buf_size);
uint8_t  ff_mlp_restart_checksum(const uint8_t *buf, unsigned int bit_size);
uint8_t  ff_mlp_calculate_parity(const uint8_t *buf, unsigned int buf_size);
void     ff_mlp_init_crc(void);

/* ---------------- bit writer (MSB first) ---------------- */
typedef struct { uint8_t *data; int bits; } PutBits;
static void pb_init(PutBits *pb, uint8_t *data){ pb->data=data; pb->bits=0; }
static void pb_put(PutBits *pb, uint64_t val, int nbits){
    for(int i=nbits-1;i>=0;i--){
        int bytepos = pb->bits>>3;
        int bitpos  = 7-(pb->bits&7);
        int bit = (int)((val>>i)&1ULL);
        if(bit) pb->data[bytepos] |= (uint8_t)(1u<<bitpos);
        pb->bits++;
    }
}
static int pb_bytes(PutBits *pb){ return (pb->bits+7)>>3; }

/* ---------------- AU builder ---------------- */
static int build_au(uint8_t *out, int is_major_sync, uint8_t stream_type,
                    const uint8_t *substr_data, int substr_bytes)
{
    uint8_t *p = out;
    uint8_t major[32];
    uint8_t substr_hdr[2];
    int total = 4 + (is_major_sync?28:0) + 2 + substr_bytes;
    if(total & 1){ fprintf(stderr,"total odd!\n"); exit(1);} 

    memset(p, 0, total);
    memset(major,0,sizeof(major));

    /* length field */
    p[0] = ((total/2)>>8)&0x0f;
    p[1] = (total/2)&0xff;

    int off = 4;

    if(is_major_sync){
        PutBits m;
        pb_init(&m, major);
        pb_put(&m, 0xf8726f, 24);
        pb_put(&m, stream_type, 8);
        if(stream_type == 0xbb){
            pb_put(&m, 0, 4);       /* group1_bits idx ->16 */
            pb_put(&m, 3, 4);       /* group2_bits idx ->0 */
            pb_put(&m, 0, 4);       /* ratebits ->48000 */
            pb_put(&m, 0xF, 4);     /* group2 ratebits ->0 */
            pb_put(&m, 0, 11);
            pb_put(&m, 0, 5);       /* channel_arrangement mono */
        } else {
            pb_put(&m, 0, 4);       /* ratebits */
            pb_put(&m, 0, 4);       /* skip4 */
            pb_put(&m, 0, 2);       /* mod0 */
            pb_put(&m, 0, 2);       /* mod1 */
            pb_put(&m, 0, 5);       /* chan_arr stream1 LR=stereo */
            pb_put(&m, 0, 2);       /* mod2 */
            pb_put(&m, 0, 13);      /* chan_arr stream2 */
        }
        pb_put(&m, 0, 24);
        pb_put(&m, 0, 24);          /* 48 skip */
        pb_put(&m, 0, 1);           /* is_vbr */
        pb_put(&m, 0, 15);          /* peak bitrate */
        pb_put(&m, 1, 4);           /* num_substreams */
        if(pb_bytes(&m) > 28){ fprintf(stderr,"major overflow %d\n", pb_bytes(&m)); exit(1);} 
        ff_mlp_init_crc();
        uint16_t c = ff_mlp_checksum16(major, 26);
        major[26] = c & 0xff;
        major[27] = (c>>8)&0xff;
        if (ff_mlp_checksum16(major, 28) != 0){ fprintf(stderr,"major cksum verify fail\n"); }
        memcpy(p+off, major, 28);
        off += 28;
    }

    /* substream header */
    {
        int extraword = 0;
        int nonrestart = is_major_sync ? 0 : 1;
        int checkdata  = 0;
        int end_field  = substr_bytes / 2;
        uint16_t sh = 0;
        sh |= (extraword&1)<<15;
        sh |= (nonrestart&1)<<14;
        sh |= (checkdata&1)<<13;
        sh |= (end_field & 0xfff);
        substr_hdr[0] = (sh>>8)&0xff;
        substr_hdr[1] = sh&0xff;
        memcpy(p+off, substr_hdr, 2);
    }
    off += 2;

    memcpy(p+off, substr_data, substr_bytes);
    off += substr_bytes;

    /* patch parity: need ((x>>4)^x)&0xF==0xF where x=xor(buf0..3)^xor(substr_hdr) */
    {
        uint8_t hdrpar = ff_mlp_calculate_parity(substr_hdr, 2);
        int fixed = 0;
        for(int b2=0;b2<256 && !fixed;b2++){
            for(int b3=0;b3<256 && !fixed;b3++){
                uint8_t x = (uint8_t)(p[0]^p[1]^b2^b3 ^ hdrpar);
                if((((x>>4)^x)&0xF)==0xF){ p[2]=(uint8_t)b2; p[3]=(uint8_t)b3; fixed=1; }
            }
        }
        if(!fixed){ fprintf(stderr,"no parity fix\n"); exit(1);} 
    }

    return off;
}

static int build_substr_au1(uint8_t *out)
{
    PutBits pb;
    memset(out,0,64);
    pb_init(&pb, out);
    pb_put(&pb, 1, 1);          /* params present */
    pb_put(&pb, 1, 1);          /* restart present */
    pb_put(&pb, 0x18F5, 13);
    pb_put(&pb, 0, 1);          /* noise_type */
    pb_put(&pb, 0, 16);         /* timestamp */
    pb_put(&pb, 0, 4);          /* min_channel */
    pb_put(&pb, 0, 4);          /* max_channel */
    pb_put(&pb, 0, 4);          /* max_matrix_channel */
    pb_put(&pb, 0, 4);          /* noise_shift */
    pb_put(&pb, 0, 23);         /* seed */
    pb_put(&pb, 0, 19);         /* skip */
    pb_put(&pb, 0, 1);          /* data_check_present */
    pb_put(&pb, 0, 8);          /* lossless_check */
    pb_put(&pb, 0, 16);         /* skip */
    pb_put(&pb, 0, 6);          /* ch_assign[0] */
    {
        int bit_size = pb.bits - 2;
        ff_mlp_init_crc();
        uint8_t rc = ff_mlp_restart_checksum(out, bit_size);
        pb_put(&pb, rc, 8);
    }
    pb_put(&pb, 0, 1);          /* PARAM_PRESENCE gate 0 */
    pb_put(&pb, 0, 1);          /* PARAM_BLOCKSIZE gate 0 */
    pb_put(&pb, 1, 1);          /* PARAM_MATRIX gate 1 */
    pb_put(&pb, 9, 4);          /* num_primitive_matrices = 9 */
    return pb_bytes(&pb);
}

static int build_substr_au2(uint8_t *out)
{
    PutBits pb;
    memset(out,0,8);
    pb_init(&pb, out);
    pb_put(&pb, 0, 1);          /* no decoding params -> read_block_data */
    return 2;
}

int main(int argc, char **argv)
{
    uint8_t au1[256], au2[256], sd1[64], sd2[8];
    uint8_t poc[512];
    static const char TAG[8] = {0x46,0x55,0x5A,0x5A,0x2D,0x54,0x41,0x47};
    int n1, n2, s1, s2;
    uint8_t stream_type = (argc>2 && !strcmp(argv[2],"truehd")) ? 0xba : 0xbb;

    s1 = build_substr_au1(sd1);
    if(s1 & 1) s1++;
    n1 = build_au(au1, 1, stream_type, sd1, s1);

    s2 = build_substr_au2(sd2);
    n2 = build_au(au2, 0, stream_type, sd2, s2);

    int pos = 0;
    memcpy(poc+pos, au1, n1); pos += n1;
    memcpy(poc+pos, TAG, 8);   pos += 8;
    memcpy(poc+pos, au2, n2); pos += n2;

    FILE *f = fopen(argv[1], "wb");
    fwrite(poc, 1, pos, f);
    fclose(f);
    fprintf(stderr, "wrote %d bytes (au1=%d,au2=%d) to %s (type=%02x)\n", pos, n1, n2, argv[1], stream_type);
    return 0;
}
